"""
Demo 1 — Toughness verifier and component-count explorer.

Builds small graphs and computes, by exhaustive subset enumeration, whether
each is 1-tough: connected and c(G - S) <= |S| for every vertex set S.
"""
from __future__ import annotations
from itertools import combinations
from typing import Iterable, Set, FrozenSet, Tuple

Graph = Tuple[Set[int], Set[FrozenSet[int]]]

def make(vs: Iterable[int], es: Iterable[Tuple[int, int]]) -> Graph:
    return set(vs), {frozenset(e) for e in es if e[0] != e[1]}

def neigh(G: Graph, v: int) -> Set[int]:
    return {x for e in G[1] if v in e for x in (e - {v})}

def comps(G: Graph) -> int:
    V, _ = G
    seen: Set[int] = set()
    k = 0
    for s in V:
        if s in seen:
            continue
        k += 1
        stack = [s]
        seen.add(s)
        while stack:
            x = stack.pop()
            for y in neigh(G, x):
                if y not in seen:
                    seen.add(y); stack.append(y)
    return k

def minus(G: Graph, S: Set[int]) -> Graph:
    V, E = G
    return V - S, {e for e in E if not (e & S)}

def is_one_tough(G: Graph) -> bool:
    V, _ = G
    if V and comps(G) != 1:
        return False
    verts = sorted(V)
    for r in range(len(verts) + 1):
        for S in combinations(verts, r):
            Sset = set(S)
            c = comps(minus(G, Sset))
            if c > 1 and c > len(Sset):
                return False
    return True

if __name__ == "__main__":
    K3 = make(range(3), [(0,1),(1,2),(2,0)])
    C5 = make(range(5), [(i,(i+1)%5) for i in range(5)])
    P4 = make(range(4), [(0,1),(1,2),(2,3)])
    for name, G in [("K3", K3), ("C5", C5), ("P4", P4)]:
        print(f"{name}: 1-tough = {is_one_tough(G)}")

"""
Demo 2 — Minimum-degree and density theorems in action.

For every 1-tough graph on n >= 3 vertices, each vertex has degree >= 2 and
the number of edges is at least n.  We verify both on several families and
show the handshake identity sum(deg) = 2|E| that links them.
"""
from __future__ import annotations
from itertools import combinations
from typing import Set, FrozenSet, Tuple

Graph = Tuple[Set[int], Set[FrozenSet[int]]]

def complete(n: int) -> Graph:
    return set(range(n)), {frozenset(e) for e in combinations(range(n), 2)}

def cycle(n: int) -> Graph:
    return set(range(n)), {frozenset((i, (i+1) % n)) for i in range(n)}

def degree(G: Graph, v: int) -> int:
    return sum(1 for e in G[1] if v in e)

def report(name: str, G: Graph) -> None:
    V, E = G
    degs = {v: degree(G, v) for v in V}
    handshake = sum(degs.values())
    print(f"{name}: |V|={len(V)} |E|={len(E)} "
          f"min-deg={min(degs.values())} "
          f"sum(deg)={handshake} 2|E|={2*len(E)} "
          f"|E|>=|V|: {len(E) >= len(V)}")

if __name__ == "__main__":
    for n in (3, 4, 5, 6):
        report(f"C{n}", cycle(n))
    for n in (3, 4, 5):
        report(f"K{n}", complete(n))

"""
Demo 3 — The triangle K3 as a full witness of the guiding theorem.

K3 is checked to be (a) minimally 1-tough, (b) (K1 u P4)-free, and
(c) Hamiltonian — every hypothesis and the conclusion of
"minimally 1-tough (K1 u P4)-free graphs are Hamiltonian".
"""
from __future__ import annotations
from itertools import combinations, permutations
from typing import Set, FrozenSet, Tuple

Graph = Tuple[Set[int], Set[FrozenSet[int]]]

def complete(n: int) -> Graph:
    return set(range(n)), {frozenset(e) for e in combinations(range(n), 2)}

def neigh(G: Graph, v: int) -> Set[int]:
    return {x for e in G[1] if v in e for x in (e - {v})}

def comps(G: Graph) -> int:
    V = set(G[0]); k = 0
    while V:
        s = V.pop(); stack = [s]
        while stack:
            x = stack.pop()
            for y in neigh(G, x) & V:
                V.discard(y); stack.append(y)
        k += 1
    return k

def is_one_tough(G: Graph) -> bool:
    V = G[0]
    if V and comps((set(V), set(G[1]))) != 1:
        return False
    verts = sorted(V)
    for r in range(len(verts)+1):
        for S in combinations(verts, r):
            Ss = set(S)
            sub = (V - Ss, {e for e in G[1] if not (e & Ss)})
            c = comps(sub)
            if c > 1 and c > len(Ss):
                return False
    return True

def minimally_one_tough(G: Graph) -> bool:
    if not is_one_tough(G):
        return False
    for e in G[1]:
        if is_one_tough((set(G[0]), set(G[1]) - {e})):
            return False
    return True

def hamiltonian(G: Graph) -> bool:
    V = sorted(G[0]); n = len(V)
    if n < 3:
        return False
    adj = lambda a, b: frozenset((a, b)) in G[1]
    for p in permutations(V[1:]):
        cyc = [V[0], *p]
        if all(adj(cyc[i], cyc[(i+1) % n]) for i in range(n)):
            return True
    return False

if __name__ == "__main__":
    K3 = complete(3)
    print("minimally 1-tough:", minimally_one_tough(K3))
    print("Hamiltonian      :", hamiltonian(K3))

