function COMPONENT_COUNT(G, S):
  alive <- V(G) \ S
  seen  <- empty set;  count <- 0
  for each start in alive:
    if start in seen: continue
    count <- count + 1
    push start on stack; add start to seen
    while stack not empty:
      u <- pop stack
      for each neighbour w of u with w in alive and w not in seen:
        add w to seen; push w
  return count

