from __future__ import annotations
from typing import Set, FrozenSet, Tuple

Graph = Tuple[Set[int], Set[FrozenSet[int]]]

def component_count(G: Graph, S: Set[int]) -> int:
    """Return c(G - S): number of connected components after deleting S.

    Linear-time flood fill over the vertices of V \\ S."""
    V = {v for v in G[0] if v not in S}
    def neigh(v: int) -> Set[int]:
        return {x for e in G[1] if v in e and not (e & S) for x in (e - {v})}
    seen: Set[int] = set()
    count = 0
    for start in V:
        if start in seen:
            continue
        count += 1
        stack = [start]; seen.add(start)
        while stack:
            x = stack.pop()
            for y in neigh(x):
                if y in V and y not in seen:
                    seen.add(y); stack.append(y)
    return count

