from itertools import combinations
from typing import Set, FrozenSet, Tuple

Graph = Tuple[Set[int], Set[FrozenSet[int]]]

def is_one_tough(G: Graph) -> bool:
    """Decide 1-toughness by enumerating every vertex subset S and checking
    c(G - S) <= |S| whenever G - S is disconnected (plus connectivity)."""
    def comps(sub: Graph) -> int:
        V = set(sub[0]); k = 0
        neigh = lambda v: {x for e in sub[1] if v in e for x in (e - {v})}
        while V:
            s = V.pop(); stack = [s]
            while stack:
                x = stack.pop()
                for y in neigh(x) & V:
                    V.discard(y); stack.append(y)
            k += 1
        return k
    V, E = G
    if V and comps(G) != 1:
        return False
    verts = sorted(V)
    for r in range(len(verts) + 1):
        for S in combinations(verts, r):
            Ss = set(S)
            sub = (V - Ss, {e for e in E if not (e & Ss)})
            c = comps(sub)
            if c > 1 and c > len(Ss):
                return False
    return True

