"""Visualization 2 — the 1-tough inequality on the cycle C_n.

For the cycle, deleting k vertices makes at most k components: the plot shows
c(C_n - S) staying on or below the line y = |S|, the boundary of 1-toughness."""
import matplotlib.pyplot as plt
from itertools import combinations

def comps_after(n: int, S: set) -> int:
    V = set(range(n)) - S
    edges = {frozenset((i, (i + 1) % n)) for i in range(n)} 
    edges = {e for e in edges if not (e & S)}
    seen, k = set(), 0
    neigh = lambda v: {x for e in edges if v in e for x in (e - {v})}
    for s in V:
        if s in seen: continue
        k += 1; stack = [s]; seen.add(s)
        while stack:
            x = stack.pop()
            for y in neigh(x):
                if y in V and y not in seen:
                    seen.add(y); stack.append(y)
    return k

def main() -> None:
    n = 9
    ks, worst = [], []
    for k in range(0, n):
        best = 0
        for S in combinations(range(n), k):
            best = max(best, comps_after(n, set(S)))
        ks.append(k); worst.append(best)
    fig, ax = plt.subplots(figsize=(6, 5))
    ax.plot(ks, ks, "k--", label="|S| (toughness boundary)")
    ax.plot(ks, worst, "o-", color="seagreen",
            label="max c(C9 - S) over |S|=k")
    ax.set_xlabel("|S|"); ax.set_ylabel("components")
    ax.set_title("Cycle C9 stays 1-tough: c(C9 - S) <= |S|")
    ax.legend(); ax.grid(alpha=0.3)
    plt.tight_layout(); plt.savefig("cycle_toughness.png", dpi=150)
    print("wrote cycle_toughness.png")

if __name__ == "__main__":
    main()
